1	const stock = new Map<string, number>([['A1', 3], ['B2', 0], ['C3', 12]]);
2	export function inStock(sku: string): boolean { return (stock.get(sku) ?? 0) > 0; }
3	/** Takes qty units if that many are left; returns whether it did. */
4	export function reserve(sku: string, qty: number): boolean {
5		const have = stock.get(sku) ?? 0;
6		if (have <= qty) { return false; }
7		stock.set(sku, have - qty);
8		return true;
9	}
